    await page.goto(`${MINE}/#/pages/history/index`, { waitUntil: 'domcontentloaded' })
    await expect(page.locator('.ui-ref8443')).toBeVisible()
    await expect(page.locator('.app-header-title')).toHaveText('历史记录')
    await expect(page.getByRole('button', { name: '汛前检查' })).toBeVisible()
    await expect(page.getByRole('button', { name: '全部工单 (14)' })).toBeVisible()
    await expect(page.getByRole('button', { name: '仅看待提交' })).toBeVisible()
    await expect(page.getByRole('button', { name: '已提交归档 (12)' })).toBeVisible()
    await expect(page.getByRole('button', { name: '继续填报' })).toBeVisible()
  })

  test('历史记录 · 求援 chip 与参考一致', async ({ page }) => {
    await page.goto(`${MINE}/#/pages/history/index`, { waitUntil: 'domcontentloaded' })
    await page.getByRole('button', { name: '汛中巡检' }).click()
    await expect(page.getByRole('button', { name: '求援工单 (2)' })).toBeVisible()
  })

  test('汛前检查 · 底部按钮文案', async ({ page }) => {
    await page.goto(`${MINE}/#/pages/inspection/index?kind=pre`, { waitUntil: 'domcontentloaded' })
    await expect(page.getByRole('button', { name: '存草稿' })).toBeVisible()
    await expect(page.getByRole('button', { name: '提 交' })).toBeVisible()
  })

  test('求援工单 · 主按钮为「提 交」', async ({ page }) => {
    await page.goto(`${MINE}/#/pages/rescue/index`, { waitUntil: 'domcontentloaded' })
    const primary = page.locator('.ref8443-action-bar .btn.orange, .ref8443-action-bar .btn.primary').first()
    await expect(primary).toHaveText('提 交')
  })

  test('参考站可达', async ({ request }) => {
    const res = await request.get(REF)
    expect(res.ok()).toBeTruthy()
  })
})

