import { test, expect } from '@playwright/test'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'

const REF = process.env.REF8443_URL ?? 'http://localhost:8443/'
const MINE = process.env.E2E_BASE_URL ?? 'http://127.0.0.1:8095'
const FONT_DIR = join(process.cwd(), 'src/static/fonts/ref8443')
const TOL = Number(process.env.REF8443_LAYOUT_TOL ?? '2')

async function fontCtx(browser: import('@playwright/test').Browser) {
  const ctx = await browser.newContext({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 1 })
  await ctx.route('https://static.figma.com/font/*', async route => {
    const tail = route.request().url().split('/').pop() ?? ''
    const map: Record<string, string> = {
      NotoSansSC-VF_2: 'NotoSansSC-VF_2.woff2',
      PlusJakartaSans_wght__2: 'PlusJakartaSans_wght__2.woff2',
    }
    const file = map[tail]
    if (!file) return route.continue()
    await route.fulfill({ body: readFileSync(join(FONT_DIR, file)), contentType: 'font/woff2' })
  })
  return ctx
}

async function ready(page: import('@playwright/test').Page) {
  await page.waitForSelector('.app-header', { timeout: 30_000 })
  await page.evaluate(async () => {
    try {
      await document.fonts.ready
    } catch {
      /* ignore */
    }
  })
  await page.waitForTimeout(400)
}

async function box(page: import('@playwright/test').Page, selector: string) {
  const loc = page.locator(selector).first()
  await loc.waitFor({ state: 'visible', timeout: 20_000 })
  return loc.boundingBox()
}

function near(a: number, b: number, tol = TOL) {
  expect(Math.abs(a - b), `${a} vs ${b}`).toBeLessThanOrEqual(tol)
}

function compareBoxes(name: string, ref: NonNullable<Awaited<ReturnType<typeof box>>>, mine: NonNullable<Awaited<ReturnType<typeof box>>>) {
  near(ref.x, mine.x, TOL)
  near(ref.y, mine.y, TOL)
  near(ref.width, mine.width, TOL)
  near(ref.height, mine.height, TOL)
}

test('8443 布局一致 · 历史记录-汛前', async ({ browser }) => {
  const ctx = await fontCtx(browser)
  const refPage = await ctx.newPage()
  const minePage = await ctx.newPage()
  await refPage.goto(REF, { waitUntil: 'domcontentloaded' })
  await minePage.goto(`${MINE}/#/pages/history/index`, { waitUntil: 'domcontentloaded' })
  await ready(refPage)
  await ready(minePage)

  const pairs: [string, string][] = [
    ['header', '.app-header'],
    ['tabs', '.tabs'],
    ['chips', '.chips'],
    ['card1', '.work-card >> nth=0'],
  ]
  for (const [label, sel] of pairs) {
    const refBox = await box(refPage, sel)
    const mineSel = sel.replace('.work-card', '.work-card').replace('.tabs', '.tabs').replace('.chips', '.chips').replace('.app-header', '.app-header')
    const mineBox = await box(minePage, mineSel)
    if (!refBox || !mineBox) throw new Error(`${label} missing box`)
    compareBoxes(label, refBox, mineBox)
  }
  await ctx.close()
})

test('8443 布局一致 · 汛前检查', async ({ browser }) => {
  const ctx = await fontCtx(browser)
  const refPage = await ctx.newPage()
  const minePage = await ctx.newPage()
  await refPage.goto(REF, { waitUntil: 'domcontentloaded' })
  await ready(refPage)
  await refPage.getByRole('button', { name: '继续填报' }).first().click()
  await refPage.waitForSelector('.form-page', { timeout: 20_000 })
  await minePage.goto(`${MINE}/#/pages/inspection/index?kind=pre`, { waitUntil: 'domcontentloaded' })
  await ready(minePage)

  const refHeader = await box(refPage, '.app-header')
  const mineHeader = await box(minePage, '.app-header')
  const refBar = await box(refPage, '.action-bar')
  const mineBar = await box(minePage, '.ref8443-action-bar')
  if (refHeader && mineHeader) compareBoxes('header', refHeader, mineHeader)
  if (refBar && mineBar) compareBoxes('action-bar', refBar, mineBar)
  await ctx.close()
})

